import threading


def reproduce(connect, service) -> str | None:
    deadlock_errors = []
    other_errors = []
    lock = threading.Lock()

    def worker(from_id, to_id, barrier):
        try:
            with connect() as conn:
                barrier.wait(timeout=15)
                try:
                    service.transfer(conn, from_id, to_id, 1)
                except Exception as e:
                    msg = f"{type(e).__name__}: {e}"
                    with lock:
                        if "deadlock" in msg.lower():
                            deadlock_errors.append(msg)
                        else:
                            other_errors.append(msg)
        except Exception as e:
            msg = f"{type(e).__name__}: {e}"
            with lock:
                if "deadlock" in msg.lower():
                    deadlock_errors.append(msg)
                else:
                    other_errors.append(msg)

    # Several rounds of simultaneous opposite-direction transfers on
    # disjoint account pairs. Each pair's two threads lock the two rows
    # in opposite order in the buggy code, so at least one pair should
    # deadlock on every run.
    for _round in range(5):
        pairs = [(i, i + 1) for i in range(1, 33, 2)]  # 16 disjoint pairs
        barrier = threading.Barrier(2 * len(pairs))
        threads = []
        for a, b in pairs:
            threads.append(threading.Thread(target=worker, args=(a, b, barrier)))
            threads.append(threading.Thread(target=worker, args=(b, a, barrier)))
        for t in threads:
            t.start()
        for t in threads:
            t.join(timeout=30)
        if deadlock_errors:
            return (
                "opposite-direction transfers deadlocked: "
                + deadlock_errors[0]
            )

    if other_errors:
        # No deadlock observed; do not claim the money/deadlock rule broke
        # for unrelated errors in this repro.
        return None
    return None

