"""Money transfer service."""
import psycopg


class InsufficientFunds(Exception):
    pass


def transfer(conn: psycopg.Connection, from_id: int, to_id: int, amount: int) -> None:
    with conn.transaction():
        # Acquire row locks in a globally consistent (ascending id) order,
        # regardless of transfer direction. Concurrent transfers between
        # the same pair in opposite directions then request the locks in
        # the same order, so no lock-ordering cycle (deadlock) can form.
        # Transfers on disjoint accounts still lock disjoint rows and
        # proceed fully in parallel.
        if from_id == to_id:
            row = conn.execute(
                "SELECT balance FROM accounts WHERE id = %s FOR UPDATE", (from_id,)
            ).fetchone()
            if row is None:
                raise ValueError("unknown account")
            if row[0] < amount:
                raise InsufficientFunds(from_id)
            conn.execute("UPDATE accounts SET balance = balance - %s WHERE id = %s", (amount, from_id))
            conn.execute("UPDATE accounts SET balance = balance + %s WHERE id = %s", (amount, to_id))
            return

        if from_id < to_id:
            first_id, second_id = from_id, to_id
        else:
            first_id, second_id = to_id, from_id

        first = conn.execute(
            "SELECT balance FROM accounts WHERE id = %s FOR UPDATE", (first_id,)
        ).fetchone()
        second = conn.execute(
            "SELECT balance FROM accounts WHERE id = %s FOR UPDATE", (second_id,)
        ).fetchone()

        if first is None or second is None:
            raise ValueError("unknown account")

        sender_balance = first[0] if from_id == first_id else second[0]
        if sender_balance < amount:
            raise InsufficientFunds(from_id)

        conn.execute("UPDATE accounts SET balance = balance - %s WHERE id = %s", (amount, from_id))
        conn.execute("UPDATE accounts SET balance = balance + %s WHERE id = %s", (amount, to_id))
